def raw_exercise():
    L = ['مشق', '', '۱۔ متن کے حوالے سے خالی جگہ پُر کریں:']
    L += [f'({r}) {s}' for r, (s, _) in zip(['i', 'ii', 'iii', 'iv', 'v'], BLANKS)]
    L += [''] + [f'{n}۔ {q}' for n, (q, _) in zip(['۲', '۳', '۴', '۵', '۶'], QS[:5])]
    L += ['۷۔ مندرجہ ذیل محاورات کو اپنے جملوں میں اس طرح استعمال کریں کہ ان کا مطلب واضح ہو جائے۔', '، '.join(w for w, _, _ in VOCAB) + '۔']
    L += ['۸۔ سیاق و سباق کا حوالہ دے کر مندرجہ ذیل اقتباس کی وضاحت کریں۔', PASSAGE]
    L += ['۹۔ مندرجہ ذیل جملوں کو درست کریں۔', '(الف) یہاں دفتر جانے کو دیر ہو رہا ہے۔', '(ب) جو ختا ہوئی، ماف کیجیے۔',
          '(ج) میرے دل میں بار بار یہ خیال پیدا ہوتی ہے۔', '(د) معلوم نہیں کب آنکھیں بند ہو جائے۔', '(ہ) عباسی نے ڈرتے ڈرتے دروازے کو کھولا۔']
    L += ['', TEACHER]
    return '\n'.join(L)


def fix_exercise(ex):
    ex['rawExercise'] = raw_exercise()
    ex['blanks'] = [dict(statement=s, answer=a) for s, a in BLANKS]
    ex['shortQuestions'] = [dict(question=q, answer=a) for q, a in QS]
    ex['vocabulary'] = [dict(word=w, meaning=m, sentence=s) for w, m, s in VOCAB]
    ex['grammar'] = GRAMMAR
    ex['teacherInstructions'] = [TEACHER.split(': ', 1)[1]]
    ex['answerNote'] = 'SpaceBook answers (the textbook prints no answers).'
    ex.pop('contextualTashreeh', None)
    ex.pop('activity', None)


